    image_patch = ImagePatch(image)
    beds = image_patch.find("bed")
    windows = image_patch.find("window")
    if not beds or not windows: return image_patch
    for bed in beds:
        for window in windows:
            if bed.overlaps_with(window.left, window.lower, window.right, window.upper):
                return bed
    return beds[0] if beds else windows[0]

